<div class="dashboard-wrap"><h1>Dashboard</h1><div class="cards"><div class="stat"><h3>Total Orders</h3><strong><?=count($orders)?></strong></div><div class="stat"><h3>Total Spent</h3><strong><?=money(array_sum(array_map(function($o){return $o->total;},$orders)))?></strong></div><div class="stat"><h3>Account</h3><strong><?=html_escape($user->username)?></strong></div></div><div class="two-col" style="margin-top:25px"><div><h2>Recent Orders</h2><table class="orders-table"><tr><th>ID</th><th>Total</th><th>Status</th></tr><?php foreach(array_slice($orders,0,8) as $o): ?><tr><td><a href="<?=base_url('order/confirmation/'.$o->id)?>">#<?=$o->id?></a></td><td><?=money($o->total)?></td><td><?=html_escape($o->status)?></td></tr><?php endforeach; ?></table></div><div><h2>Account</h2><p><?=html_escape($user->name)?></p><p><?=html_escape($user->email)?></p><p><?=html_escape($user->phone)?></p><a class="btn btn-primary" href="<?=base_url('profile')?>">Edit Profile</a></div></div></div>
